/// Look up a bundled brand mark by Simple Icons slug.
pub(crate) fn brand_mark(slug: &str) -> Option<&'static BrandMark> {
    let want = slug.trim().to_ascii_lowercase();
    BRAND_MARKS.iter().find(|m| m.slug == want)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn marks_have_valid_fill_and_path() {
        for m in BRAND_MARKS {
            assert!(m.fill.starts_with('#') && m.fill.len() == 7, "{}", m.slug);
            assert!(
                m.path.starts_with('M') || m.path.starts_with('m'),
                "{}",
                m.slug
            );
            assert!(!m.path.contains('<') && !m.path.contains('"'), "{}", m.slug);
        }
        assert!(brand_mark("Docker").is_some());
        assert!(brand_mark("nope").is_none());
    }
}
